const queryClient = new QueryClient();
const basePath = import.meta.env.BASE_URL.replace(/\/$/, "");
const publishableKeyFromHost = (clerkInternal as unknown as { publishableKeyFromHost?: (host: string, fallback?: string) => string }).publishableKeyFromHost ?? ((_: string, fallback?: string) => fallback || "");
const clerkPubKey = publishableKeyFromHost(window.location.hostname, import.meta.env.VITE_CLERK_PUBLISHABLE_KEY);
const clerkProxyUrl = import.meta.env.VITE_CLERK_PROXY_URL;
const currency = (n: number, compact = false) => new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", notation: compact ? "compact" : "standard", maximumFractionDigits: compact ? 1 : 0 }).format(n);
const date = (value: string | null | undefined) => value ? new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }).format(new Date(value)) : "—";
const since = (value: string) => { const days = Math.max(1, Math.floor((Date.now() - new Date(value).getTime()) / 86400000)); return days === 1 ? "yesterday" : `${days} days ago`; };

function Logo({ dark = false }: { dark?: boolean }) {
  return <Link href="/" className="flex items-center gap-3" data-testid="link-logo">
    <span className={`grid h-10 w-10 place-items-center rounded-[13px] ${dark ? "bg-[#d7795d] text-[#4a2029]" : "bg-[#722c3b] text-[#f7f0e6]"}`}>
      <Leaf size={21} strokeWidth={1.8} />
    </span>
    <span className={`leading-none ${dark ? "text-[#f7f0e6]" : "text-foreground"}`}><strong className="display block text-lg font-semibold tracking-tight">Wild Haven</strong><small className="mono mt-1 block text-[9px] uppercase opacity-70">Conservation / staff</small></span>
  </Link>;
}

function Home() {
  const { isSignedIn } = useAuth();
  if (isSignedIn) return <Redirect to="/dashboard" />;
  return <main className="paper-grain min-h-[100dvh] overflow-hidden bg-background text-foreground">
    <div className="mx-auto flex min-h-[100dvh] max-w-7xl flex-col px-6 py-7 lg:px-12">
      <header className="flex items-center justify-between"><Logo /><div className="flex items-center gap-3"><span className="mono hidden text-[10px] uppercase tracking-[.18em] text-muted-foreground sm:block">Internal operations workspace</span><Link href="/sign-in" className="rounded-full border border-border px-4 py-2 text-sm font-semibold text-primary transition hover:bg-secondary" data-testid="link-sign-in">Staff sign in</Link></div></header>
      <section className="grid flex-1 items-center gap-14 py-20 lg:grid-cols-[1.1fr_.9fr] lg:py-24">
        <div className="rise-in"><p className="mono mb-7 text-xs uppercase tracking-[.28em] text-accent">The work behind the wild</p><h1 className="display max-w-3xl text-6xl font-semibold leading-[.94] tracking-[-.045em] text-primary sm:text-8xl">Good work needs a <em className="text-accent">clear view.</em></h1><p className="mt-8 max-w-lg text-lg leading-8 text-muted-foreground">A private workspace for the people turning every gift into protected habitat, safer journeys, and a future for the species we share this place with.</p><div className="mt-10 flex flex-wrap items-center gap-5"><Link href="/sign-in" className="group inline-flex items-center gap-3 rounded-full bg-primary px-6 py-3.5 text-sm font-semibold text-primary-foreground transition hover:-translate-y-0.5 hover:bg-[#5d2230]" data-testid="link-access-portal">Enter the staff portal <ChevronRight size={16} className="transition group-hover:translate-x-1" /></Link><span className="flex items-center gap-2 text-sm text-muted-foreground"><ShieldCheck size={16} className="text-accent" /> Secure by design</span></div></div>
        <div className="relative rise-in rise-in-2"><div className="absolute -inset-8 rounded-[45%] bg-[#ead7c8] opacity-50 blur-3xl" /><div className="relative overflow-hidden rounded-[34px] border border-[#d9c0b5] bg-[#d9c0b5] p-3 shadow-2xl shadow-[#722c3b]/10"><div className="relative flex min-h-[440px] flex-col justify-between overflow-hidden rounded-[25px] bg-[#722c3b] p-7 text-[#f7f0e6]"><div className="absolute -right-20 -top-24 h-80 w-80 rounded-full border border-[#d7795d]/30" /><div className="absolute -bottom-28 -left-20 h-96 w-96 rounded-full border border-[#d7795d]/20" /><div className="relative flex justify-between"><span className="mono text-[10px] uppercase tracking-[.22em] text-[#e7b4a4]">Field note / 04.24</span><Sprout size={20} className="text-[#d7795d]" /></div><div className="relative"><p className="display max-w-sm text-4xl leading-tight">“Conservation is a long conversation with the land.”</p><p className="mono mt-5 text-[10px] uppercase tracking-[.16em] text-[#e7b4a4]">— Dr. Amara Okafor, field director</p></div><div className="relative flex items-end justify-between"><div><div className="display text-6xl font-semibold text-[#d7795d]">14.8k</div><div className="mono text-[10px] uppercase tracking-[.15em] text-[#f7f0e6]/60">acres in care</div></div><div className="rounded-full border border-[#f7f0e6]/20 px-3 py-1.5 text-xs">est. 1998</div></div></div></div></div>
      </section>
      <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-border py-5 text-xs text-muted-foreground"><span>For the people who keep showing up.</span><span className="mono uppercase tracking-[.14em]">Wild Haven Wildlife Conservation</span></footer>
    </div>
  </main>;
}

const nav = [
  { href: "/dashboard", label: "Overview", icon: HomeIcon },
  { href: "/donors", label: "Donors", icon: Users },
  { href: "/donations", label: "Donations", icon: CircleDollarSign },
  { href: "/campaigns", label: "Campaigns", icon: Sprout },
  { href: "/impact", label: "Impact", icon: BarChart3 },
];

function AppShell({ children }: { children: React.ReactNode }) {
  const [location, setLocation] = useLocation(); const [mobile, setMobile] = useState(false); const { signOut } = useClerk();
  const { data: staff } = useGetCurrentStaff({ query: { queryKey: getGetCurrentStaffQueryKey() } });
  const { user } = useUser();
  return <div className="paper-grain flex min-h-[100dvh] bg-background text-foreground">
    <aside className={`portal-sidebar fixed inset-y-0 left-0 z-40 flex w-[250px] flex-col border-r border-sidebar-border px-5 py-6 text-sidebar-foreground transition-transform lg:static lg:translate-x-0 ${mobile ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="mb-10 flex items-center justify-between"><Logo dark /><button onClick={() => setMobile(false)} className="text-sidebar-foreground/60 lg:hidden" data-testid="button-close-menu"><X size={20} /></button></div>
      <div className="mb-3 px-3 mono text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/45">Workspace</div>
      <nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobile(false)} className={`nav-item flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm ${location === href ? "bg-sidebar-accent text-sidebar-accent-foreground shadow-sm" : "text-sidebar-foreground/65 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground"}`} data-testid={`link-nav-${label.toLowerCase()}`}><Icon size={17} strokeWidth={1.8} /><span>{label}</span>{href === "/impact" && <span className="ml-auto rounded-full bg-sidebar-primary/20 px-1.5 py-0.5 mono text-[9px] text-sidebar-primary">NEW</span>}</Link>)}</nav>
      <div className="mt-9 mb-3 px-3 mono text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/45">Account</div>
      <nav className="space-y-1"><Link href="/settings" className={`nav-item flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm ${location === "/settings" ? "bg-sidebar-accent text-sidebar-accent-foreground" : "text-sidebar-foreground/65 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground"}`} data-testid="link-nav-settings"><Settings size={17} strokeWidth={1.8} /> Settings</Link><button onClick={() => signOut({ redirectUrl: basePath || "/" })} className="nav-item flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm text-sidebar-foreground/65 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground" data-testid="button-sign-out"><ArrowDownRight size={17} strokeWidth={1.8} /> Sign out</button></nav>
      <div className="mt-auto rounded-2xl border border-sidebar-border bg-sidebar-accent/50 p-4"><div className="mb-3 flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[#d7795d]" /><span className="mono text-[9px] uppercase tracking-[.16em] text-sidebar-foreground/60">All systems healthy</span></div><p className="text-xs leading-5 text-sidebar-foreground/55">Your work today supports <strong className="font-medium text-sidebar-foreground/90">seven active habitats.</strong></p></div>
      <div className="mt-5 flex items-center gap-3 border-t border-sidebar-border pt-5"><span className="grid h-9 w-9 place-items-center rounded-full bg-sidebar-primary text-xs font-bold text-sidebar-primary-foreground">{staff?.initials || user?.firstName?.slice(0, 2).toUpperCase() || "WH"}</span><div className="min-w-0"><p className="truncate text-sm font-medium">{staff?.name || user?.fullName || "Staff member"}</p><p className="truncate text-[11px] text-sidebar-foreground/50">{staff?.role || "Conservation team"}</p></div></div>
    </aside>
    {mobile && <button className="fixed inset-0 z-30 bg-[#35151d]/35 lg:hidden" onClick={() => setMobile(false)} aria-label="Close navigation" data-testid="button-overlay-menu" />}
     <div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur-md sm:px-8"><button onClick={() => setMobile(true)} className="mr-3 rounded-lg p-2 text-muted-foreground hover:bg-secondary lg:hidden" data-testid="button-open-menu"><Menu size={21} /></button><div className="flex items-center gap-3"><span className="mono hidden text-[10px] uppercase tracking-[.18em] text-muted-foreground sm:block">Wild Haven /</span><span className="text-sm font-medium text-primary">{nav.find((n) => n.href === location)?.label || "Settings"}</span></div><div className="flex items-center gap-4"><button className="relative rounded-lg p-2 text-muted-foreground hover:bg-secondary" title="Activity notifications" data-testid="button-notifications"><Activity size={19} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-accent" /></button><span className="hidden h-5 w-px bg-border sm:block" /><span className="mono hidden text-[10px] uppercase tracking-[.12em] text-muted-foreground md:block">September / 2026</span></div></header><main className="mx-auto max-w-[1440px] px-5 py-8 sm:px-8 lg:px-10">{children}</main></div>
  </div>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mono mb-2 text-[10px] uppercase tracking-[.23em] text-accent">{eyebrow}</p><h1 className="display text-4xl font-semibold tracking-tight text-primary sm:text-5xl">{title}</h1>{description && <p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div>;
}
function Button({ children, onClick, variant = "primary", testId, type = "button" }: { children: React.ReactNode; onClick?: () => void; variant?: "primary" | "quiet" | "danger"; testId: string; type?: "button" | "submit" }) {
  return <button type={type} onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition hover:-translate-y-0.5 active:translate-y-0 ${variant === "primary" ? "bg-primary text-primary-foreground hover:bg-[#5d2230]" : variant === "danger" ? "border border-destructive/30 text-destructive hover:bg-destructive/10" : "border border-border bg-card text-primary hover:bg-secondary"}`} data-testid={testId}>{children}</button>;
}
function LoadingRows({ count = 4 }: { count?: number }) { return <div className="space-y-3">{Array.from({ length: count }).map((_, i) => <div className="skeleton h-16 rounded-xl" key={i} />)}</div>; }
function ErrorState({ retry }: { retry: () => void }) { return <div className="portal-card flex flex-col items-center justify-center rounded-2xl py-16 text-center"><ShieldCheck size={25} className="mb-4 text-destructive" /><h3 className="font-semibold text-primary">A quiet moment in the field</h3><p className="mt-2 max-w-sm text-sm text-muted-foreground">We couldn’t load this view. Check your connection and try again.</p><Button onClick={retry} variant="quiet" testId="button-retry">Try again</Button></div>; }
function EmptyState({ icon: Icon, title, detail, action }: { icon: typeof Users; title: string; detail: string; action?: React.ReactNode }) { return <div className="portal-card flex flex-col items-center justify-center rounded-2xl py-16 text-center"><span className="mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><Icon size={22} /></span><h3 className="font-semibold text-primary">{title}</h3><p className="mt-2 max-w-sm text-sm text-muted-foreground">{detail}</p>{action && <div className="mt-5">{action}</div>}</div>; }

function StatCard({ label, value, change, note, icon: Icon, accent = false }: { label: string; value: string; change: number; note: string; icon: typeof TrendingUp; accent?: boolean }) {
  return <div className={`portal-card relative overflow-hidden rounded-2xl p-5 ${accent ? "bg-primary text-primary-foreground" : ""}`}><div className="flex items-start justify-between"><span className={`mono text-[10px] uppercase tracking-[.15em] ${accent ? "text-primary-foreground/65" : "text-muted-foreground"}`}>{label}</span><span className={`rounded-lg p-2 ${accent ? "bg-primary-foreground/10 text-accent" : "bg-secondary text-primary"}`}><Icon size={17} /></span></div><div className="mt-7 flex items-end justify-between gap-2"><strong className={`display text-3xl font-semibold ${accent ? "text-primary-foreground" : "text-primary"}`}>{value}</strong><span className={`mb-1 flex items-center gap-1 text-xs font-semibold ${change >= 0 ? accent ? "text-[#e7b4a4]" : "text-[#39735f]" : "text-destructive"}`}>{change >= 0 ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}{Math.abs(change)}%</span></div><p className={`mt-1 text-xs ${accent ? "text-primary-foreground/55" : "text-muted-foreground"}`}>{note}</p></div>;
}

function Dashboard() {
  const summaryQ = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } });
  const activityQ = useListActivity({ limit: 7 }, { query: { queryKey: getListActivityQueryKey({ limit: 7 }) } });
  const summary = summaryQ.data; const trend = summary?.donationTrend || []; const max = Math.max(...trend.map((p) => p.value), 1);
  if (summaryQ.isLoading) return <><PageHeading eyebrow="Good morning" title="Field overview" /><LoadingRows count={5} /></>;
  if (summaryQ.isError) return <><PageHeading eyebrow="Good morning" title="Field overview" /><ErrorState retry={() => summaryQ.refetch()} /></>;
  return <div className="rise-in"><PageHeading eyebrow="Good morning, conservation team" title="Field overview" description="A clear read on the generosity, campaigns, and habitats moving forward today." action={<Button onClick={() => window.print()} variant="quiet" testId="button-export-overview"><FileText size={16} /> Export overview</Button>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Total raised" value={currency(summary?.totalRaised || 0, true)} change={summary?.totalRaisedChange || 0} note="vs. previous 30 days" icon={CircleDollarSign} accent /><StatCard label="Donor community" value={(summary?.donorCount || 0).toLocaleString()} change={summary?.donorCountChange || 0} note="active supporters" icon={Users} /><StatCard label="Active campaigns" value={String(summary?.activeCampaignCount || 0).padStart(2, "0")} change={0} note="across 4 regions" icon={Sprout} /><StatCard label="Monthly recurring" value={currency(summary?.monthlyRecurring || 0, true)} change={summary?.monthlyRecurringChange || 0} note="reliable habitat care" icon={TrendingUp} /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><section className="portal-card rounded-2xl p-5 sm:p-6"><div className="mb-8 flex items-start justify-between"><div><p className="mono text-[10px] uppercase tracking-[.17em] text-muted-foreground">Donation health</p><h2 className="display mt-1 text-2xl font-semibold text-primary">Momentum, month by month</h2></div><span className="rounded-lg bg-secondary p-2 text-primary"><TrendingUp size={17} /></span></div><div className="relative h-56"><div className="absolute inset-0 flex flex-col justify-between text-[10px] text-muted-foreground/70">{[100, 75, 50, 25, 0].map((n) => <div key={n} className="flex items-center gap-3"><span className="w-7 text-right mono">{currency((max * n) / 100, true)}</span><span className="h-px flex-1 border-t border-dashed border-border" /></div>)}</div><svg viewBox="0 0 700 200" preserveAspectRatio="none" className="absolute bottom-0 left-12 right-0 h-[calc(100%-4px)] w-[calc(100%-48px)] overflow-visible">{trend.length > 1 && <><path className="chart-area" d={`M0,${200 - (trend[0].value / max) * 180} ${trend.map((p, i) => `L${(i / (trend.length - 1)) * 700},${200 - (p.value / max) * 180}`).join(" ")} L700,200 L0,200 Z`} /><path className="chart-line" d={trend.map((p, i) => `${i === 0 ? "M" : "L"}${(i / (trend.length - 1)) * 700},${200 - (p.value / max) * 180}`).join(" ")} /></>}</svg></div><div className="ml-10 mt-3 flex justify-between text-[10px] text-muted-foreground">{trend.map((p) => <span key={p.label} className="mono">{p.label}</span>)}</div></section>
      <section className="portal-card rounded-2xl p-5 sm:p-6"><div className="mb-6 flex items-start justify-between"><div><p className="mono text-[10px] uppercase tracking-[.17em] text-muted-foreground">Campaign pulse</p><h2 className="display mt-1 text-2xl font-semibold text-primary">Where it’s landing</h2></div><Link href="/campaigns" className="text-xs font-semibold text-accent hover:underline" data-testid="link-view-campaigns">View all</Link></div><div className="space-y-5">{(summary?.campaignProgress || []).slice(0, 4).map((c) => <div key={c.id} data-testid={`metric-campaign-${c.id}`}><div className="mb-2 flex items-center justify-between gap-2"><span className="truncate text-sm font-medium text-primary">{c.name}</span><span className="mono text-[10px] text-muted-foreground">{c.percent}%</span></div><div className="h-2 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-accent transition-all duration-700" style={{ width: `${Math.min(c.percent, 100)}%` }} /></div></div>)}</div></section></div>
      <div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><section className="portal-card rounded-2xl p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><p className="mono text-[10px] uppercase tracking-[.17em] text-muted-foreground">Recent movement</p><h2 className="display mt-1 text-2xl font-semibold text-primary">The latest good news</h2></div><Link href="/donations" className="text-xs font-semibold text-accent hover:underline" data-testid="link-view-ledger">Open ledger</Link></div>{activityQ.isLoading ? <LoadingRows count={4} /> : activityQ.isError ? <ErrorState retry={() => activityQ.refetch()} /> : !activityQ.data?.length ? <EmptyState icon={Activity} title="No activity yet" detail="When your team makes a move, it will appear here." /> : <div className="divide-y divide-border">{activityQ.data.map((item) => <div className="flex items-center gap-4 py-3.5" key={item.id} data-testid={`activity-item-${item.id}`}><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-secondary text-primary">{item.type === "donation" ? <CircleDollarSign size={16} /> : item.type === "campaign" ? <Sprout size={16} /> : item.type === "report" ? <FileText size={16} /> : <Users size={16} />}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-primary">{item.title}</p><p className="truncate text-xs text-muted-foreground">{item.detail}</p></div><span className="mono whitespace-nowrap text-[10px] text-muted-foreground">{since(item.createdAt)}</span></div>)}</div>}</section><section className="rounded-2xl bg-[#ead7c8] p-6 text-[#4a2029]"><div className="flex items-start justify-between"><Leaf size={22} /><span className="mono text-[10px] uppercase tracking-[.15em] opacity-60">Field note</span></div><p className="display mt-12 text-3xl leading-tight">Every record is a story of someone choosing to care.</p><p className="mt-5 text-sm leading-6 opacity-75">Keep the details close. They’re what let the work stay human as it grows.</p></section></div>
  </div>;
}

function Modal({ title, children, close }: { title: string; children: React.ReactNode; close: () => void }) { return <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#35151d]/35 p-0 backdrop-blur-sm sm:items-center sm:p-6"><div className="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-t-3xl border border-border bg-card p-6 shadow-2xl sm:rounded-3xl"><div className="mb-6 flex items-start justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-accent">Staff workspace</p><h2 className="display mt-1 text-3xl font-semibold text-primary">{title}</h2></div><button onClick={close} className="rounded-lg p-2 text-muted-foreground hover:bg-secondary" data-testid="button-close-modal"><X size={19} /></button></div>{children}</div></div>; }
function Field({ label, name, value, onChange, type = "text", required = false, placeholder }: { label: string; name: string; value: string | number; onChange: (v: string) => void; type?: string; required?: boolean; placeholder?: string }) { return <label className="block space-y-1.5"><span className="text-xs font-semibold text-primary">{label}</span><input name={name} type={type} value={value} onChange={(e) => onChange(e.target.value)} required={required} placeholder={placeholder} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none transition placeholder:text-muted-foreground/60 focus:border-accent focus:ring-2 focus:ring-accent/15" data-testid={`input-${name}`} /></label>; }
function SelectField({ label, name, value, onChange, options }: { label: string; name: string; value: string; onChange: (v: string) => void; options: string[] }) { return <label className="block space-y-1.5"><span className="text-xs font-semibold text-primary">{label}</span><select name={name} value={value} onChange={(e) => onChange(e.target.value)} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm capitalize outline-none focus:border-accent" data-testid={`select-${name}`}>{options.map((o) => <option value={o} key={o}>{o.replace("_", " ")}</option>)}</select></label>; }

function DonorForm({ existing, close }: { existing?: Donor; close: () => void }) {
  const qc = useQueryClient(); const [form, setForm] = useState({ name: existing?.name || "", email: existing?.email || "", phone: existing?.phone || "", city: existing?.city || "" }); const create = useCreateDonor(); const update = useUpdateDonor();
  const save = (e: React.FormEvent) => { e.preventDefault(); const data: DonorInput = { ...form, phone: form.phone || null, city: form.city || null }; const onSuccess = () => { qc.invalidateQueries({ queryKey: getListDonorsQueryKey() }); if (existing) qc.invalidateQueries({ queryKey: getGetDonorQueryKey(existing.id) }); close(); }; existing ? update.mutate({ id: existing.id, data }, { onSuccess }) : create.mutate({ data }, { onSuccess }); };
  return <form onSubmit={save} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Full name" name="name" value={form.name} onChange={(v) => setForm({ ...form, name: v })} required placeholder="e.g. Celia Hart" /><Field label="Email address" name="email" type="email" value={form.email} onChange={(v) => setForm({ ...form, email: v })} required placeholder="celia@example.com" /><Field label="Phone" name="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: v })} placeholder="+1 555 000 0000" /><Field label="City" name="city" value={form.city} onChange={(v) => setForm({ ...form, city: v })} placeholder="Portland, OR" /></div><div className="flex justify-end gap-3 pt-3"><Button onClick={close} variant="quiet" testId="button-cancel-donor">Cancel</Button><Button type="submit" testId="button-save-donor">{(create.isPending || update.isPending) && <Loader2 size={15} className="animate-spin" />} {existing ? "Save changes" : "Add donor"}</Button></div></form>;
}

function Donors() {
  const [search, setSearch] = useState(""); const [modal, setModal] = useState<"create" | "edit" | "detail" | null>(null); const [selected, setSelected] = useState<Donor>(); const [confirm, setConfirm] = useState<Donor>(); const qc = useQueryClient();
  const q = useListDonors({ search: search || undefined, limit: 100 }, { query: { queryKey: getListDonorsQueryKey({ search: search || undefined, limit: 100 }) } }); const del = useDeleteDonor();
  const show = (d: Donor, m: "edit" | "detail") => { setSelected(d); setModal(m); };
  return <div className="rise-in"><PageHeading eyebrow="Relationships" title="Donors" description="The people who make the work possible, kept close and cared for." action={<Button onClick={() => setModal("create")} testId="button-create-donor"><Plus size={16} /> Add donor</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><label className="relative flex-1"><Search size={17} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by name, email, or city" className="h-11 w-full rounded-xl border border-input bg-card pl-10 pr-3 text-sm outline-none focus:border-accent focus:ring-2 focus:ring-accent/15" data-testid="input-search-donors" /></label><span className="mono flex items-center rounded-xl border border-border bg-card px-4 text-[10px] uppercase tracking-[.12em] text-muted-foreground">{q.data?.length || 0} records</span></div>{q.isLoading ? <LoadingRows /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : !q.data?.length ? <EmptyState icon={Users} title={search ? "No donors found" : "Your donor book is open"} detail={search ? "Try a different name, email, or city." : "Add your first donor record to start building the circle of care."} action={!search && <Button onClick={() => setModal("create")} testId="button-empty-create-donor"><Plus size={16} /> Add first donor</Button>} /> : <div className="portal-card overflow-hidden rounded-2xl"><div className="hidden grid-cols-[1.5fr_1.3fr_1fr_.75fr_30px] gap-4 border-b border-border px-5 py-3 sm:grid"><span className="mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">Donor</span><span className="mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">Contact</span><span className="mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">Last gift</span><span className="mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">Given</span><span /></div><div className="divide-y divide-border">{q.data.map((d) => <div key={d.id} className="grid gap-3 px-5 py-4 transition hover:bg-secondary/50 sm:grid-cols-[1.5fr_1.3fr_1fr_.75fr_30px] sm:items-center sm:gap-4" data-testid={`row-donor-${d.id}`}><button onClick={() => show(d, "detail")} className="flex min-w-0 items-center gap-3 text-left" data-testid={`button-view-donor-${d.id}`}><span className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[#ead7c8] text-xs font-bold text-primary">{d.name.split(" ").map((x) => x[0]).join("").slice(0, 2)}</span><span className="min-w-0"><strong className="block truncate text-sm font-semibold text-primary">{d.name}</strong><small className="text-xs text-muted-foreground">{d.donationCount} gifts</small></span></button><div className="truncate text-sm text-muted-foreground">{d.email}<span className="block text-xs">{d.city || "No city listed"}</span></div><div className="text-sm text-primary">{date(d.lastGiftAt)}<span className="block text-xs text-muted-foreground">Joined {date(d.createdAt)}</span></div><strong className="text-sm text-primary">{currency(d.totalGiven)}</strong><div className="flex gap-1"><button onClick={() => show(d, "edit")} className="rounded-lg p-2 text-muted-foreground hover:bg-secondary hover:text-primary" title="Edit donor" data-testid={`button-edit-donor-${d.id}`}><Pencil size={15} /></button><button onClick={() => setConfirm(d)} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" title="Delete donor" data-testid={`button-delete-donor-${d.id}`}><Trash2 size={15} /></button></div></div>)}</div></div>}{modal === "create" && <Modal title="Add a donor" close={() => setModal(null)}><DonorForm close={() => setModal(null)} /></Modal>}{modal === "edit" && selected && <Modal title="Edit donor" close={() => setModal(null)}><DonorForm existing={selected} close={() => setModal(null)} /></Modal>}{modal === "detail" && selected && <Modal title={selected.name} close={() => setModal(null)}><div className="space-y-5"><div className="flex items-center gap-3 rounded-2xl bg-secondary p-4"><span className="grid h-12 w-12 place-items-center rounded-full bg-[#ead7c8] font-semibold text-primary">{selected.name.split(" ").map((x) => x[0]).join("").slice(0, 2)}</span><div><p className="font-semibold text-primary">{selected.email}</p><p className="text-sm text-muted-foreground">{selected.city || "No city listed"} · {selected.phone || "No phone listed"}</p></div></div><div className="grid grid-cols-2 gap-3"><div className="rounded-xl border border-border p-4"><p className="mono text-[9px] uppercase text-muted-foreground">Lifetime giving</p><p className="display mt-2 text-2xl font-semibold text-primary">{currency(selected.totalGiven)}</p></div><div className="rounded-xl border border-border p-4"><p className="mono text-[9px] uppercase text-muted-foreground">Gifts made</p><p className="display mt-2 text-2xl font-semibold text-primary">{selected.donationCount}</p></div></div><div className="flex justify-end gap-3"><Button onClick={() => setModal("edit")} variant="quiet" testId={`button-detail-edit-${selected.id}`}><Pencil size={15} /> Edit record</Button></div></div></Modal>}{confirm && <Modal title="Remove this donor?" close={() => setConfirm(undefined)}><p className="text-sm leading-6 text-muted-foreground">This permanently removes <strong className="text-primary">{confirm.name}</strong> from the donor book. Donation history may be affected.</p><div className="mt-6 flex justify-end gap-3"><Button onClick={() => setConfirm(undefined)} variant="quiet" testId="button-cancel-delete-donor">Keep record</Button><Button onClick={() => { del.mutate({ id: confirm.id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListDonorsQueryKey() }); setConfirm(undefined); } }); }} variant="danger" testId="button-confirm-delete-donor"><Trash2 size={15} /> Remove donor</Button></div></Modal>}</div>;
}

function DonationForm({ existing, close }: { existing?: Donation; close: () => void }) {
  const qc = useQueryClient(); const donorsQ = useListDonors({ limit: 100 }, { query: { queryKey: getListDonorsQueryKey({ limit: 100 }) } }); const campaignsQ = useListCampaigns({ limit: 100 }, { query: { queryKey: getListCampaignsQueryKey({ limit: 100 }) } }); const create = useCreateDonation(); const update = useUpdateDonation();
  const [form, setForm] = useState({ donorId: String(existing?.donorId || donorsQ.data?.[0]?.id || ""), amount: String(existing?.amount || ""), frequency: existing?.frequency || "one_time", status: existing?.status || "completed", campaignId: String(existing?.campaignId || ""), donatedAt: existing?.donatedAt?.slice(0, 10) || new Date().toISOString().slice(0, 10) });
  const set = (k: string, v: string) => setForm((x) => ({ ...x, [k]: v })); const save = (e: React.FormEvent) => { e.preventDefault(); const data = { donorId: Number(form.donorId), amount: Number(form.amount), frequency: form.frequency as "one_time" | "monthly", status: form.status as DonationStatus, campaignId: form.campaignId ? Number(form.campaignId) : null, donatedAt: new Date(form.donatedAt).toISOString() }; const done = () => { qc.invalidateQueries({ queryKey: getListDonationsQueryKey() }); if (existing) qc.invalidateQueries({ queryKey: getGetDonationQueryKey(existing.id) }); close(); }; existing ? update.mutate({ id: existing.id, data }, { onSuccess: done }) : create.mutate({ data }, { onSuccess: done }); };
  return <form onSubmit={save} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><label className="block space-y-1.5 sm:col-span-2"><span className="text-xs font-semibold text-primary">Donor</span><select value={form.donorId} onChange={(e) => set("donorId", e.target.value)} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none focus:border-accent" required data-testid="select-donorId"><option value="">Select a donor</option>{donorsQ.data?.map((d) => <option key={d.id} value={d.id}>{d.name} — {d.email}</option>)}</select></label><Field label="Amount" name="amount" type="number" value={form.amount} onChange={(v) => set("amount", v)} required placeholder="250" /><Field label="Gift date" name="donatedAt" type="date" value={form.donatedAt} onChange={(v) => set("donatedAt", v)} required /><SelectField label="Frequency" name="frequency" value={form.frequency} onChange={(v) => set("frequency", v)} options={["one_time", "monthly"]} /><SelectField label="Status" name="status" value={form.status} onChange={(v) => set("status", v)} options={["completed", "pending", "refunded"]} /><label className="block space-y-1.5 sm:col-span-2"><span className="text-xs font-semibold text-primary">Campaign</span><select value={form.campaignId} onChange={(e) => set("campaignId", e.target.value)} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none focus:border-accent" data-testid="select-campaignId"><option value="">General conservation fund</option>{campaignsQ.data?.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label></div><div className="flex justify-end gap-3 pt-3"><Button onClick={close} variant="quiet" testId="button-cancel-donation">Cancel</Button><Button type="submit" testId="button-save-donation">{(create.isPending || update.isPending) && <Loader2 size={15} className="animate-spin" />} {existing ? "Save changes" : "Record donation"}</Button></div></form>;
}

